    callWithPointer {
    uniffiRustCallWithError(FfiException) { _status ->
    UniffiLib.INSTANCE.uniffi_konstruado_ffi_fn_method_konstruadoapp_abandonar(
        it, FfiConverterString.lower(`obraId`),_status)
}
    }
    
    

    
