     * escritorio (escucha en 17432, sin modo celular): solo para pruebas en PC.
     */
    @Throws(FfiException::class) fun `nuevo`(`datosDir`: kotlin.String, `socksHost`: kotlin.String?, `socksPort`: kotlin.UShort?, `destinos`: List<kotlin.String>, `escritorio`: kotlin.Boolean): KonstruadoApp {
