/**
 * @suppress
 */
public object FfiConverterTypeKonstruadoApp: FfiConverter<KonstruadoApp, Pointer> {

    override fun lower(value: KonstruadoApp): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): KonstruadoApp {
        return KonstruadoApp(value)
    }

    override fun read(buf: ByteBuffer): KonstruadoApp {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: KonstruadoApp) = 8UL

    override fun write(value: KonstruadoApp, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



data class AvisoVista (
    var `texto`: kotlin.String, 
